#!/usr/bin/env bash
# hermes-bot-icons — install function-matched bot avatars on any Hermes install.
# Self-contained: all 8 icons embedded (no network, no deps beyond bash + base64).
#
# Usage:
#   curl -fsSL https://raw.githubusercontent.com/valicen-davidsaunders/hermes-bot-icons/main/install.sh | bash
#   .../install.sh --dry-run     # show what would be installed, change nothing
#   .../install.sh --list        # list profile -> icon mapping only
#   HERMES_HOME=/path ...        # non-default Hermes home
#
# Behaviour: writes <profile>/assets/avatar.png (plus the root/default profile),
# always backing up any existing avatar to avatar.png.bak-<timestamp>.
# The desktop app reads avatars live; reopen the Bots page to refresh.
set -euo pipefail

DRY=0; LIST=0
for arg in "$@"; do
  case "$arg" in
    --dry-run|-n) DRY=1 ;;
    --list|-l)    LIST=1 ;;
    --help|-h)    grep '^# ' "$0" | sed 's/^# //'; exit 0 ;;
    *) echo "unknown flag: $arg (see --help)" >&2; exit 2 ;;
  esac
done

HERMES_HOME="${HERMES_HOME:-$HOME/.hermes}"
if [ ! -d "$HERMES_HOME" ]; then
  echo "error: HERMES_HOME not found at $HERMES_HOME (set HERMES_HOME=... to override)" >&2
  exit 1
fi
TS="$(date +%Y%m%d-%H%M%S)"

# ---------------------------------------------------------------- embedded icons
read -r -d '' B64_HERMES <<'B64' || true
