decode_icon() {
  case "$1" in
    hermes)    printf '%s' "$B64_HERMES" ;;
    it)        printf '%s' "$B64_IT" ;;
    cmp)       printf '%s' "$B64_CMP" ;;
    finance)   printf '%s' "$B64_FINANCE" ;;
    legal)     printf '%s' "$B64_LEGAL" ;;
    pmo)       printf '%s' "$B64_PMO" ;;
    sales)     printf '%s' "$B64_SALES" ;;
    marketing) printf '%s' "$B64_MARKETING" ;;
    *) echo "unknown icon: $1" >&2; return 1 ;;
  esac | base64 -d
}

# Map a profile name to an icon by function (fuzzy; order matters - specific first).
map_icon() {
  local name="${1,,}"
  case "$name" in
    "" | hermes) echo hermes ;;
    *marketing* | *mkt* | *brand* | *content*) echo marketing ;;
    fin | fin-* | fin_* | *finance* | *account* | *cfo*) echo finance ;;
    *legal* | *lgl* | *counsel* | *compliance*) echo legal ;;
    *pmo* | *project* | *program*) echo pmo ;;
    *sales* | *sls* | *revenue* | *crm*) echo sales ;;
    *cmp* | *chief* | *staff* | coo* | cro*) echo cmp ;;
    it | ito* | it-* | *ito*) echo it ;;
    *dev* | *ops* | *admin* | *infra*) echo it ;;
    *) echo hermes ;;
  esac
}

install_one() { # $1 = label, $2 = profile home dir
  local label="$1" home="$2" assets target icon
  icon="$(map_icon "$label")"
  assets="$home/assets"; target="$assets/avatar.png"
  if [ "$LIST" = 1 ]; then echo "$label -> $icon.png"; return; fi
  if [ "$DRY" = 1 ]; then
    if [ -f "$target" ]; then
      echo "would replace $label -> $icon.png (backup existing)"
    else
      echo "would create $label -> $icon.png"
    fi
    return
  fi
  if [ -f "$target" ]; then cp -p "$target" "$target.bak-$TS"; fi
  mkdir -p "$assets"
  decode_icon "$icon" > "$target"
  if [ "$(head -c4 "$target" | od -An -tx1 | tr -d ' \n')" != "89504e47" ]; then
    echo "  ERROR: $label wrote invalid PNG - restoring backup" >&2
    if [ -f "$target.bak-$TS" ]; then mv -f "$target.bak-$TS" "$target"; fi
    return 1
  fi
  echo "installed $label -> $icon.png ($(wc -c < "$target" | tr -d ' ') bytes)"
}

echo "HERMES_HOME: $HERMES_HOME"
if [ -f "$HERMES_HOME/config.yaml" ]; then
  install_one "default" "$HERMES_HOME"
fi
if [ -d "$HERMES_HOME/profiles" ]; then
  for d in "$HERMES_HOME"/profiles/*/; do
    [ -d "$d" ] || continue
    install_one "$(basename "$d")" "${d%/}"
  done
else
  echo "(no profiles dir - root/default profile only)"
fi
echo "done. Reopen the Bots page in the desktop app to see the new avatars."
